def find_largest(numbers):
    largest = numbers[0]
    for num in numbers[1:]:
        if num > largest:
            largest = num
    return largest

The function starts with the first number and updates largest whenever it finds a bigger value.

def is_even(n):
    return n % 2 == 0

An integer is even when the remainder after division by 2 is 0.

def count_vowels(text):
    count = 0
    for char in text.lower():
        if char in "aeiou":
            count += 1
    return count

Converting the string to lowercase makes the count ignore letter case.

for number in range(5, 16, 2):
    print(number)

This prints 5, 7, 9, 11, 13, and 15.

def remove_duplicates(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

The set tracks values already seen, and each value is added to the result only on its first occurrence, preserving order.

import re
from collections import Counter

def word_frequencies(sentence):
    words = re.split(r"[^\w]+", sentence.lower())
    return dict(Counter(word for word in words if word))

The sentence is converted to lowercase, split at any punctuation or whitespace, and the nonempty words are counted.

def mean_of_numeric_strings(strings):
    total = 0.0
    count = 0
    for s in strings:
        try:
            value = float(s)
        except (ValueError, TypeError):
            continue
        total += value
        count += 1
    if count == 0:
        raise ValueError("No valid numbers found.")
    return total / count

Invalid strings are skipped, and ValueError is raised if no valid numbers remain.

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

Lists are flattened recursively, while non-list values are added as individual elements, preserving order. For example, flatten([1, [2, [3, 4]], 5]) returns [1, 2, 3, 4, 5].

def second_largest(numbers):
    largest = None
    second = None
    for num in numbers:
        if largest is None or num > largest:
            second = largest
            largest = num
        elif num != largest and (second is None or num > second):
            second = num
    if second is None:
        raise ValueError("Need at least two distinct numbers.")
    return second

The function tracks the largest and second-largest distinct values in a single pass and ignores duplicates of the largest value.

scores = {"Alice": 92, "Bob": 85, "Charlie": 78}
print(scores["Bob"])

This creates a dictionary mapping names to scores and prints Bob's score, 85.

def common_elements(list1, list2):
    return list(set(list1) & set(list2))

Converting both lists to sets removes duplicates, and the & operator returns the elements found in both.

def string_lengths(strings):
    return {s: len(s) for s in strings}

For example, string_lengths(["apple", "fig"]) returns {"apple": 5, "fig": 3}.

def group_by_first_letter(words):
    groups = {}
    for word in words:
        if not word:
            continue
        key = word[0].lower()
        groups.setdefault(key, []).append(word)
    return groups

Empty strings are skipped, and the lowercase first letter is used as the key so uppercase and lowercase are grouped together.

def is_balanced(s):
    depth = 0
    for char in s:
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

The counter tracks unmatched opening parentheses. The string is unbalanced if a closing parenthesis appears without a match or if any opening parentheses remain at the end.

from collections import defaultdict

def group_anagrams(words):
    groups = defaultdict(list)
    for word in words:
        key = "".join(sorted(word.lower()))
        groups[key].append(word)
    return list(groups.values())

The grouping key is the word converted to lowercase with its letters sorted alphabetically. Anagrams contain the same letters, so they produce the same key; for example, "Listen" and "silent" both become "eilnst".

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("Capacity must be positive.")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

Accessed or updated keys are moved to the end as most recently used. When capacity is exceeded, the least recently used item at the front is removed.

def linear_search(items, target):
    for index, value in enumerate(items):
        if value == target:
            return index
    return -1

The function checks each item in order and returns the first matching index, or -1 if no match is found.

def factorial(n):
    if n < 0:
        raise ValueError("n must be nonnegative.")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

For n = 0 or 1, the loop does not run and the function returns 1.

def sum_to_n(n):
    return n * (n + 1) // 2

This uses the formula 1 + 2 + ... + n = n(n + 1)/2. For n = 0 it returns 0, and for n = 10 it returns 55.

def reverse_string(s):
    result = ""
    for char in s:
        result = char + result
    return result

Each character is placed in front of the previous characters, producing the reversed string.

def binary_search(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

The search range is halved each step, giving O(log n) time.

import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

The function checks divisors only up to the square root of n, because any factor larger than the square root would pair with a smaller factor already checked. It also skips even divisors after checking 2.

def length_of_longest_substring(s):
    last_seen = {}
    start = 0
    best = 0
    for end, char in enumerate(s):
        if char in last_seen and last_seen[char] >= start:
            start = last_seen[char] + 1
        last_seen[char] = end
        best = max(best, end - start + 1)
    return best

The sliding window keeps a substring with no repeated characters. The right edge moves forward one character at a time. If a character repeats inside the window, the left edge moves just past its previous position. Each character is processed once, so the time complexity is O(n).

from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([start])
    parent = {start: None}
    while queue:
        vertex = queue.popleft()
        if vertex == goal:
            path = []
            while vertex is not None:
                path.append(vertex)
                vertex = parent[vertex]
            return path[::-1]
        for neighbor in graph.get(vertex, []):
            if neighbor not in parent:
                parent[neighbor] = vertex
                queue.append(neighbor)
    return None

BFS explores vertices in order of distance from the start, so the first time it reaches the goal, the reconstructed path is a shortest path. It returns None if the goal is unreachable.

The for statement is missing a colon, and the loop body must be on an indented line. Corrected code:
for i in range(5):
    print(i)

The default list is created only once when the function is defined, so every call without an items argument shares and modifies the same list. Use None as the default instead:
def add_item(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

For n = 0, the function calls factorial(-1), then factorial(-2), and so on, never reaching n == 1, so it causes infinite recursion and a RecursionError. Negative inputs have the same problem. A corrected version:
def factorial(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer.")
    if n < 0:
        raise ValueError("n must be nonnegative.")
    if n <= 1:
        return 1
    return n * factorial(n - 1)
